__ht__function(g, rect, comp, data, view) {var x = rect.x;
var y = rect.y;
var width = rect.width;
var height = rect.height;

var borderColor = comp.getColor('borderColor');
var borderWidth = comp.getValue('borderWidth');
var background = comp.getColor('background');
var valueVisible = comp.getValue('valueVisible');
var valueColor = comp.getColor('valueColor');
var valueFont = comp.getValue('valueFont');
var maxValue = comp.getValue('maxValue');



var value = comp.getValue('value');
var foreColor = comp.getColor('foreColor');


//valuewidth=[0.4*width,0.4*width];


// draw background
if (background) {
    g.fillStyle = background;
    g.beginPath();
    g.rect(x, y, width, height);
    g.fill();
}
debugger
var theValue=0;
var theWidth=0;
for (var i = 0; i < value.length; i ++) {  //遍历数组
    theValue+=value[i];

    g.fillStyle = valueColor[i];
    g.beginPath();
    g.rect(theWidth, y, value[i], height);   
    g.fill();
    if (valueVisible) {
        ht.Default.drawText(g, value[i] + '', valueFont, foreColor, theWidth, y, value[i], height, 'center', 'middle');
    }
    theWidth=theValue/maxValue*width;
}


// draw border
if (borderWidth && borderColor) {
    ht.Default.drawBorder(g, borderColor, x, y, width, height, borderWidth);
}}
